style.css:
@-moz-document regexp("http://*") {
/**
 * Glitch Interface Theme (v10.3)
 *
 * - PERFORMANCE: Removed the glowing red outline on hover for text elements.
 * - PERFORMANCE: Simplified buttons to a solid color instead of a gradient.
 * - Static HUD viewport frame.
 * - Text "glitches" into existence.
 * - Themed checkboxes and radio buttons.
 */

/* === Section 1: Global Page & UI Styling === */

html, body {
  background-color: #111 !important; background-image: radial-gradient(circle at top center, #3a3a3a, #111) !important;
  min-height: 100%; perspective: 1500px;
}

/* HUD Viewport Frame */
body::before, body::after { content: ''; position: fixed; z-index: 9999; pointer-events: none; background: #ff5555; box-shadow: 0 0 5px #ff1a1a, 0 0 10px #ff1a1a; }
body::before { left: 0; right: 0; height: 5px; top: 0; box-shadow: 0 0 5px #ff1a1a, 0 0 10px #ff1a1a, 0 calc(100vh - 5px) 0 0 #ff5555; }
body::after { top: 0; bottom: 0; width: 5px; left: 0; box-shadow: 0 0 5px #ff1a1a, 0 0 10px #ff1a1a, calc(100vw - 5px) 0 0 0 #ff5555; }

/* Re-themed Scrollbar */
::-webkit-scrollbar { width: 12px; }
::-webkit-scrollbar-track { background: #220000; }
::-webkit-scrollbar-thumb { background: linear-gradient(180deg, #ffffff, #ffadad); border-radius: 6px; border: 2px solid #220000; }
::-webkit-scrollbar-thumb:hover { background: linear-gradient(180deg, #ffffff, #ff5555); }

/* Custom highlight */
::selection, ::-moz-selection { background: rgba(80, 80, 80, 0.9); color: transparent !important; -webkit-background-clip: text; background-clip: text; }

/* Interactive Images */
img { filter: grayscale(100%); transition: filter 0.5s ease-in-out, transform 0.4s ease-out, box-shadow 0.4s ease-out; }
img:hover { filter: grayscale(0%); }

/* Re-themed Horizontal Dividers (<hr>) */
hr { border: none; height: 2px; margin: 2em 0; background: linear-gradient(90deg, #fff, #ff5555, #fff, #ff5555, #fff); background-size: 200% auto; animation: red-shimmer 4s linear infinite; }

/* Themed Form Inputs */
input[type="text"], input[type="email"], input[type="password"], input[type="search"], textarea { background-color: #1a0505 !important; color: #ffffff !important; border-radius: 4px; padding: 8px 10px; border: 2px solid transparent; border-image: linear-gradient(110deg, #ffadad, #ffffff, #ffadad) 1; transition: all 0.2s ease-in-out; }
input[type="text"]:focus, input[type="email"]:focus, input[type="password"]:focus, input[type="search"]:focus, textarea:focus { outline: none; box-shadow: 0 0 10px rgba(255, 85, 85, 0.8); }

/* --- SIMPLIFIED Buttons --- */
button, input[type="submit"] {
  background-color: #4d0000 !important; /* Solid dark red */
  color: #ffffff !important; font-weight: bold; border: 1px solid #ff5555;
  border-radius: 4px; padding: 10px 16px; cursor: pointer;
  transition: background-color 0.2s ease-in-out; /* Smooth color change on hover */
}
button:hover, input[type="submit"]:hover {
  background-color: #660000 !important; /* Slightly brighter red on hover */
}

/* Themed Checkboxes & Radio Buttons */
input[type="checkbox"], input[type="radio"] { appearance: none; -webkit-appearance: none; position: relative; top: 2px; width: 16px; height: 16px; margin: 0 5px 0 0; background-color: #1a0505; border: 2px solid #ff5555; cursor: pointer; transition: all 0.2s ease-in-out; }
input[type="radio"] { border-radius: 50%; }
input[type="checkbox"] { border-radius: 2px; }
input[type="checkbox"]:hover, input[type="radio"]:hover { background-color: #4d0000; }
input[type="checkbox"]:checked, input[type="radio"]:checked { background-color: #ff5555; border-color: #fff; }
input[type="checkbox"]:checked::after, input[type="radio"]:checked::after { content: ''; display: block; }
input[type="checkbox"]:checked::after { width: 4px; height: 8px; border: solid #1a0505; border-width: 0 3px 3px 0; transform: translate(3px, 0px) rotate(45deg); }
input[type="radio"]:checked::after { width: 6px; height: 6px; background: #1a0505; border-radius: 50%; transform: translate(3px, 3px); }


/* === Section 2: 3D Tilt Effect === */
img, blockquote { transform-style: preserve-3d; transition: transform 0.4s ease-out, box-shadow 0.4s ease-out; }
img:hover, blockquote:hover { transform: scale(1.05) rotateY(-8deg) rotateX(5deg) translateZ(20px); box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5); }


/* === Section 3: Animation Keyframes === */
@keyframes red-shimmer { 0% { background-position: 200% center; } 100% { background-position: -200% center; } }
@keyframes glitch-on-load {
  0%   { text-shadow: 0 0 #ff3333, 0 0 #33ffff; transform: translate(0, 0); }
  20%  { text-shadow: -2px 2px #ff3333, 2px -2px #33ffff; transform: translate(-1px, 1px); }
  40%  { text-shadow: 2px -2px #ff3333, -2px 2px #33ffff; transform: translate(1px, -1px); }
  60%  { text-shadow: 0 0 #ff3333, 0 0 #33ffff; transform: translate(0, 0); }
  80%  { text-shadow: -3px 3px 2px #ff3333, 3px -3px 2px #33ffff; }
  100% { text-shadow: 0 0 0 transparent; transform: translate(0, 0); }
}


/* === Section 4: Main Text Style (Unified) === */
p, h1, h2, h3, h4, h5, h6, span, a, li, blockquote, strong, em, b, i, code, .inline-code {
  background: linear-gradient(110deg, #f0f0f0 40%, #ffffff 48%, #ff4d4d 50%, #ffffff 52%, #f0f0f0 60%);
  background-size: 200% auto; -webkit-background-clip: text; background-clip: text; color: transparent !important;
  animation: glitch-on-load 0.8s ease-out, red-shimmer 4s linear 0.8s infinite;
  /* The padding and transition for the hover outline have been removed */
}


/* === Section 5: Special States & Overrides === */
blockquote { margin-left: 1em; padding-left: 1.5em; border-left: 5px solid transparent; border-image: linear-gradient(to bottom, #fff, #ff5555, #fff) 1; }
/* The hover outline rule that was here has been REMOVED. */
}
